
// Compile with : gcc -pthread -o threadtest.out threadtest.c

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

pthread_mutex_t mymutex;

void *charatatime(void *str)
{
	char * ptr;
	int c;
	setbuf(stdout,NULL);
	for(ptr=(char *)str;c=*ptr++;) putc(c, stdout);
}

int main()
{
	pthread_t thread1, thread2;
	pthread_create (&thread1, NULL, charatatime, "");
	pthread_create (&thread2, NULL, charatatime, "");
	pthread_join(thread1, NULL);
	pthread_join(thread2, NULL);
	exit(0);
}


